def auditer(dossiers):
    groupes = {}
    for g, reel, predit in dossiers:
        if g not in groupes:
            groupes[g] = {'vp': 0, 'fp': 0, 'fn': 0, 'vn': 0}
        if reel and predit:
            groupes[g]['vp'] += 1
        elif not reel and predit:
            groupes[g]['fp'] += 1
        elif reel and not predit:
            groupes[g]['fn'] += 1
        else:
            groupes[g]['vn'] += 1
    resultat = {}
    for g, c in groupes.items():
        n = c['vp'] + c['fp'] + c['fn'] + c['vn']
        positifs = c['vp'] + c['fn']
        negatifs = c['fp'] + c['vn']
        selectionnes = c['vp'] + c['fp']
        resultat[g] = {
            'effectif': n,
            'selection': round(selectionnes / n, 4) if n else 0.0,
            'tvp': round(c['vp'] / positifs, 4) if positifs else 0.0,
            'tfp': round(c['fp'] / negatifs, 4) if negatifs else 0.0,
            'precision': round(c['vp'] / selectionnes, 4) if selectionnes else 0.0}
    return resultat

