question.answer:
def criteres(audit, seuil):
    noms = sorted(audit)
    a, b = audit[noms[0]], audit[noms[1]]
    return {'parite': abs(a['selection'] - b['selection']) < seuil,
            'chances': abs(a['tvp'] - b['tvp']) < seuil,
            'calibration': abs(a['precision'] - b['precision']) < seuil}

def nb_satisfaits(audit, seuil):
    c = criteres(audit, seuil)
    return sum(1 for v in c.values() if v)

def contrefactuel(dossier, decision, actionnables, pas, bornes):
    meilleur = None
    for cle in sorted(actionnables):
        bas, haut = bornes[cle]
        p = pas[cle]
        depart = dossier[cle]
        n_max = int(max((haut - depart) / p, (depart - bas) / p)) + 1
        for n in range(1, n_max + 1):
            candidats = []
            for valeur in (depart - n * p, depart + n * p):
                if bas <= valeur <= haut:
                    candidats.append(valeur)
            for valeur in sorted(candidats):
                essai = dict(dossier)
                essai[cle] = valeur
                if decision(essai):
                    if meilleur is None or n < meilleur[0]:
                        meilleur = (n, cle, valeur)
                    break
            if meilleur is not None and meilleur[0] <= n:
                break
    return (meilleur[1], meilleur[2]) if meilleur else None

